B.bca=new A.V("3. N\xc3O COMPARTILHAMENTO",null,B.dI,null,null,null,null,null,null,null,null,null,null)
B.bdR=new A.V("A Impetus Tecnologia n\xe3o vende, aluga ou compartilha seus dados pessoais com terceiros ou anunciantes para fins publicit\xe1rios sob nenhuma hip\xf3tese.",null,B.eF,null,null,null,null,null,null,null,null,null,null)
